void verify(Context& c,uint64_t rva){auto p=std::find_if(std::begin(pins),std::end(pins),[&](const Pin& x){return x.rva==rva;});need(p!=std::end(pins),"Region type native entry lacks its exact image extent/digest fact");c.verify_hash(rva,p->bytes,p->sha);}
template<class R,class... A>R call(Context& c,uint64_t rva,A... args){verify(c,rva);R value{};auto error=modular::detail::invoke(reinterpret_cast<R(*)(A...)>(c.image+rva),&value,args...);need(!error,"Region type native call failed RVA="+std::to_string(rva)+" SEH="+std::to_string(error)+"; no replay");return value;}
template<class... A>void call_void(Context& c,uint64_t rva,A... args){verify(c,rva);auto error=modular::detail::invoke_void(reinterpret_cast<void(*)(A...)>(c.image+rva),args...);need(!error,"Region type native call failed RVA="+std::to_string(rva)+" SEH="+std::to_string(error)+"; no replay");}
std::vector<uintptr_t> array(Context& c,uintptr_t p,size_t maximum=1000000){auto data=c.read<uintptr_t>(p+8);auto n=c.read<int32_t>(p+16),cap=c.read<int32_t>(p+20);need(n>=0&&size_t(n)<=maximum&&cap>=n&&cap<=1000000&&(!cap||data),"Region type native roster extent differs");std::vector<uintptr_t> rows;std::set<uintptr_t> unique;for(int32_t i=0;i<n;++i){auto value=c.read<uintptr_t>(data+size_t(i)*8);need(value&&unique.insert(value).second,"Region type native roster contains null or repeated member");rows.push_back(value);}need(c.read<uintptr_t>(p+8)==data&&c.read<int32_t>(p+16)==n&&c.read<int32_t>(p+20)==cap,"Region type native roster changed during capture");return rows;}
struct Region {uintptr_t map=0,root=0,object=0;int32_t id=-1;std::vector<uintptr_t> all;};
