struct Span {uintptr_t begin,end,capacity;};
size_t extent(const Span& s,size_t stride,size_t limit){need(s.begin<=s.end&&s.end<=s.capacity&&(s.begin||(!s.end&&!s.capacity))&&(s.end-s.begin)%stride==0&&(s.capacity-s.begin)%stride==0&&(s.end-s.begin)/stride<=limit,"Region original polygon vector extent differs");return size_t((s.end-s.begin)/stride);}
Json shape(Context& c,uintptr_t p){auto data=c.read<uintptr_t>(p+0x18);need(data!=0,"Region original polygon data is absent");auto paths=c.read<Span>(data);auto count=extent(paths,24,1000000);Json out=Json::array();size_t budget=1000000;for(size_t n=0;n<count;++n){auto points=c.read<Span>(paths.begin+n*24);auto size=extent(points,16,budget);budget-=size;Json values=Json::array();for(size_t k=0;k<size;++k)values.push_back(c.read<std::array<int64_t,2>>(points.begin+k*16));out.push_back(values);}return out;}
Json shapes(Context& c,uintptr_t region){Json values=Json::array();for(int32_t n=0;n<4;++n){alignas(16)std::array<unsigned char,0x70> owner{};bool ready=false;std::string cause;Json value;try{call_void(c,0x362450,static_cast<void*>(owner.data()),static_cast<const void*>(ptr(region+0x78)),n);ready=true;value=shape(c,uintptr_t(owner.data()));}catch(const std::exception& e){cause=e.what();}if(ready)try{call_void(c,0xf15a0,static_cast<void*>(owner.data()));}catch(const std::exception& e){if(!cause.empty())cause+="; ";cause+=std::string("Region polygon cleanup: ")+e.what();}need(cause.empty(),cause);values.push_back(value);}return values;}
